        let raw = Config::parse_env();
        let errors = Config::validate(raw).unwrap_err();
        assert!(errors.iter().any(|e| e.message.contains("placeholder")));
        remove_env("APP_ENV");
        remove_env("MCP_OAUTH_ISSUER");
    }

