// Internal HTTP client for CommonCal backend API.
//
// In v1, authenticates via MCP_INTERNAL_API_KEY header.
// Future: mTLS with workload identity.

use serde::Deserialize;

#[derive(Clone)]
pub struct InternalClient {
    api_base: url::Url,
    api_key: String,
